{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user is created without explicitly disabling console access, potentially allowing console login."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  name = \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\"\n  path = \"/\"\n}\nresource \"aws_iam_user_login_profile\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  user = aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name\n  pgp_key = \"keybase:someone_that_exists\"\n}\nresource \"aws_iam_access_key\" \"privesc15-PassExistingRoleToNewLambdaThenInvoke-user\" {\n  user = aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name\n  status = \"Inactive\"\n}",
  "fix_summary": "Added aws_iam_user_login_profile with a pgp_key and an aws_iam_access_key with status Inactive to prevent console access and ensure programmatic access is inactive by default."
}
